:where(.kami-root .kami-ui-steps li) { display:flex;align-items:center;gap:var(--kami-gap);padding:var(--kami-pad-lg-y) var(--kami-pad-lg-x);border:var(--kami-border-w) solid transparent;border-radius:var(--kami-r-sm); }
:where(.kami-root .kami-ui-steps .is-current) { border-color:var(--kami-accent);background-color:var(--kami-accent-soft); }
:where(.kami-root .kami-ui-step-mark) { display:grid;place-items:center;flex:0 0 2em;min-height:2em;border:var(--kami-border-w) solid var(--kami-line-strong);border-radius:50%; }
