:where(.kami-root .kami-ui-resources) { display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,var(--kami-items-min)),1fr));gap:var(--kami-gap); }
:where(.kami-root .kami-layout) { display:flex;gap:var(--kami-gap);min-width:0;max-width:100%; }
:where(.kami-root .kami-layout>*) { min-width:0; }
:where(.kami-root [data-kami-layout-kind="stack"]) { flex-direction:column; }
