  --kami-map-fog-fill: #1a1f26;
  --kami-map-fog-edge: #3a434e;
  --kami-map-fog-fg: #6b7784;
  --kami-map-here-fill: rgba(122, 162, 247, .22);
  --kami-map-here-ring: rgba(122, 162, 247, .50);
  --kami-map-edge: #4b5563;
  --kami-map-edge-dash: #3a434e;
}

