  }
  api.audit = audit;

  /* 清掉本脚本自己残留的按钮（比如旧版本 JSON 里声明过、现在不该有的） */
  function cleanOwnStale() {
    try {
      if (typeof getScriptButtons !== 'function' || typeof replaceScriptButtons !== 'function' || typeof getScriptId !== 'function') { return; }
      var mine = getScriptButtons() || [];
