        });
      }
    } catch (e) { }
  }

  /* ───────── 全局 API / 注销 / 启动 ───────── */

  function expose() {
    var api = {
      version: VERSION,
      scan: scan,
      /* 「🧪 消息前端」接管时调用：拆掉美化与流式提示（原生块恢复酒馆原样） */
      release: function () { hideStreamHint(); undressAll(); },
      /* 流式中正在扣的思维链（消息前端用来边生成边显示「思考中 N 字」）：没有在搬时返回 null */
      live: function () {
