      解析器被 build/kami-doc.mjs 的 presetParseSource 内联进 40-预设设置.js 与 50-引导.js，
      两个面板天然同源。**绝不许在 40 / 50 里各写一套** —— 那正是 _preset-cards.js 头部
      抱怨过的第三次分叉（同一组件写两套，注释标记与开关高亮已经因此丢过两次）。 */
const DIY_SUFFIX = ' | diy_write_style';
/* 自定义文风只能落在「写作指导」这个分区里。分区边界由本文件的层级配对逻辑给出（不是字符串切分），
   这里只提供认区用的名字提示；调用方也可以额外传锚点卡片名提高命中率。 */
const DIY_LAYER_HINT = '写作指导';
/* prompt_order 的结构断言常量（写入前必须对得上，对不上就放弃写入、不许猜） */
const DIY_ORDER_COUNT = 1;
const DIY_CHAR_ID = 100001;

// ---------- 基础工具（无正则） ----------

function countOccurrences(text, sub) {
  if (typeof text !== 'string' || typeof sub !== 'string' || sub.length === 0) return 0;
  let count = 0;
  let i = 0;
  for (;;) {
    i = text.indexOf(sub, i);
    if (i < 0) return count;
    count++;
    i += sub.length;
  }
}

function isPureDigits(text) {
  if (typeof text !== 'string' || text.length === 0) return false;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c < 48 || c > 57) return false;
  }
  return true;
}

// 去掉首尾的 🔻 / 🔺，再 trim。用于包裹区与层级的内名比对。
// 注意：🔻/🔺 是代理对（2 个 UTF-16 码元），必须按 2 个码元切，不能用 slice(1)。
function stripArrowEnds(text) {
  let s = String(text);
  let changed = true;
  while (changed) {
    changed = false;
    while (s.startsWith(ARROW_OPEN) || s.startsWith(ARROW_CLOSE)) {
      s = s.slice(2);
      changed = true;
    }
    while (s.endsWith(ARROW_OPEN) || s.endsWith(ARROW_CLOSE)) {
      s = s.slice(0, s.length - 2);
      changed = true;
    }
  }
  return s.trim();
}

// 第一个 {{// ... }} 的内部文本（去掉包裹符），没有则为 null
function firstComment(content) {
  if (typeof content !== 'string') return null;
  const start = content.indexOf('{{//');
  if (start < 0) return null;
  const end = content.indexOf('}}', start);
  if (end < 0) return null;
  return content.slice(start + 4, end);
}

// 抽 content 里所有 setvar::名字::值 片段
function parseSetvars(content) {
  const out = [];
  if (typeof content !== 'string') return out;
  let i = 0;
  for (;;) {
    i = content.indexOf('setvar::', i);
    if (i < 0) return out;
    const rest = content.slice(i + 8);
    let end = rest.indexOf('}}');
    if (end < 0) end = rest.length;
    const body = rest.slice(0, end);
    const sep = body.indexOf('::');
    if (sep >= 0) {
      const name = body.slice(0, sep).trim();
      const value = body.slice(sep + 2).trim();
      out.push({ name: name, value: value, numeric: isPureDigits(value), raw: body });
    }
    i += 8;
  }
}

// 从模型登记表 content 里解析 emoji 表：每个 {{// ... }} 块按行切
function parseModelTable(content) {
  const models = [];
  if (typeof content !== 'string') return models;
  let i = 0;
  for (;;) {
    const start = content.indexOf('{{//', i);
    if (start < 0) return models;
    const end = content.indexOf('}}', start);
    if (end < 0) return models;
    const inner = content.slice(start + 4, end);
    const lines = inner.split(NL);
    for (const lineRaw of lines) {
      const line = lineRaw.trim();
      if (line.length === 0) continue;
      const c = line.indexOf(FULL_COLON);
      if (c <= 0) continue;
      const emoji = line.slice(0, c).trim();
      const label = line.slice(c + 1).trim();
      if (emoji.length > 0 && label.length > 0) {
        models.push({ emoji: emoji, label: label, line: lineRaw, source: end });
      }
    }
    i = end + 2;
  }
}

// 变量条目 -> 卡片（范围卡 / 数字卡）
function buildVarCards(entry) {
  const numeric = parseSetvars(entry.content).filter((s) => s.numeric);
  const used = [];
  const cards = [];
  const consumedNames = [];
  for (const v of numeric) {
    if (consumedNames.indexOf(v.name) >= 0) continue;
    let base = null;
    if (v.name.endsWith('_min')) base = v.name.slice(0, v.name.length - 4);
    else if (v.name.endsWith('_max')) base = v.name.slice(0, v.name.length - 4);
    if (base !== null && base.length > 0) {
      const minName = base + '_min';
      const maxName = base + '_max';
      const minVar = numeric.find((x) => x.name === minName);
      const maxVar = numeric.find((x) => x.name === maxName);
      if (minVar && maxVar) {
        consumedNames.push(minName, maxName);
        cards.push({
          type: 'range',
          identifier: entry.identifier,
          entryName: entry.name,
          base: base,
          min: { name: minName, value: minVar.value, number: Number(minVar.value) },
          max: { name: maxName, value: maxVar.value, number: Number(maxVar.value) },
          swapped: Number(minVar.value) > Number(maxVar.value),
        });
        continue;
      }
    }
    consumedNames.push(v.name);
    cards.push({
      type: 'number',
      identifier: entry.identifier,
      entryName: entry.name,
      name: v.name,
      value: v.value,
      number: Number(v.value),
    });
  }
  for (const v of numeric) used.push(v.name);
  return { cards: cards, numericVars: numeric, allVars: parseSetvars(entry.content), usedNames: used };
}

// ---------- 主解析 ----------

function parsePreset(preset) {
  const issues = [];
  const orders = preset && preset.prompt_order ? preset.prompt_order : [];
  if (orders.length === 0) throw new Error('prompt_order 为空，无法解析');
  const orderArr = orders[0].order || [];
  const prompts = preset.prompts || [];
  const byId = new Map();
  for (const p of prompts) byId.set(p.identifier, p);

  // 1) 按 order 展开，主键用完整 identifier，短号取后 6 位
  const entries = [];
  orderArr.forEach((o, index) => {
    const p = byId.get(o.identifier);
    if (!p) {
      issues.push({ level: 'error', kind: 'prompt-not-found', identifier: o.identifier, index: index });
      return;
    }
    const nameRaw = typeof p.name === 'string' ? p.name : '';
    const name = nameRaw.trim();
    const content = typeof p.content === 'string' ? p.content : '';
    const openCount = countOccurrences(name, ARROW_OPEN);
    const closeCount = countOccurrences(name, ARROW_CLOSE);
    let kind = 'plain';
    if (name.endsWith(ARROW_OPEN) && openCount === 2) kind = 'wrapper-open';
    else if (name.endsWith(ARROW_CLOSE) && closeCount === 2) kind = 'wrapper-close';
    else if (name.endsWith(ARROW_OPEN) && openCount === 1) kind = 'layer-open';
    else if (name.endsWith(ARROW_CLOSE) && closeCount === 1) kind = 'layer-close';
    else if (openCount > 0 || closeCount > 0) {
      issues.push({ level: 'warn', kind: 'arrow-name-not-matching-any-pattern', identifier: p.identifier, name: name });
    }
    entries.push({
      index: index,
      identifier: p.identifier,
      shortId: p.identifier.slice(Math.max(0, p.identifier.length - 6)),
      nameRaw: nameRaw,
      name: name,
      enabled: o.enabled === undefined ? p.enabled : o.enabled,
      promptEnabled: p.enabled,
      marker: p.marker === true,
      role: p.role,
      systemPrompt: p.system_prompt,
      injectionDepth: p.injection_depth,
      injectionOrder: p.injection_order,
      injectionPosition: p.injection_position,
      forbidOverrides: p.forbid_overrides,
      content: content,
      contentLength: content.length,
      kind: kind,
      orderEnabled: o.enabled,
      comment: firstComment(content),
      commentFlat: null,
      region: null,
      card: null,
      models: [],
      modelLabels: [],
      modelExclusive: false,
      lockedOpen: false,
      note: null,
    });
  });
  for (const e of entries) e.commentFlat = e.comment === null ? null : e.comment.trim();

  // 2) 区间识别：栈式配对（层级 / 包裹区）
  const regions = [];
  const stack = [];
  const closeRegion = (region, node) => {
    region.closeIndex = node.index;
    region.closeEntry = node;
    regions.push(region);
  };
  for (const e of entries) {
    if (e.kind === 'layer-open' || e.kind === 'wrapper-open') {
      stack.push({
        kind: e.kind === 'layer-open' ? 'layer' : 'wrapper',
        name: stripArrowEnds(e.name),
        openIndex: e.index,
        openEntry: e,
        closeIndex: -1,
        closeEntry: null,
        children: [],
        cards: [],
        activeCards: [],
        segments: [],
        ownItems: [],
      });
      continue;
    }
    if (e.kind === 'layer-close' || e.kind === 'wrapper-close') {
      const want = e.kind === 'layer-close' ? 'layer' : 'wrapper';
      const wantName = stripArrowEnds(e.name);
      let found = -1;
      for (let s = stack.length - 1; s >= 0; s--) {
        if (stack[s].kind === want && stack[s].name === wantName) {
          found = s;
          break;
        }
      }
      if (found < 0) {
        issues.push({ level: 'error', kind: 'region-close-without-open', identifier: e.identifier, name: e.name, index: e.index });
        e.role = 'region-orphan';
        continue;
      }
      for (let s = stack.length - 1; s > found; s--) {
        issues.push({
          level: 'error',
          kind: 'region-not-closed',
          name: stack[s].name,
          kindOfRegion: stack[s].kind,
          openIndex: stack[s].openIndex,
          closedBy: e.name,
        });
        closeRegion(stack[s], e);
      }
      stack.length = found + 1;
      const region = stack.pop();
      closeRegion(region, e);
      continue;
    }
    if (stack.length > 0) stack[stack.length - 1].children.push(e);
  }
  for (let s = stack.length - 1; s >= 0; s--) {
    issues.push({ level: 'error', kind: 'region-never-closed', name: stack[s].name, kindOfRegion: stack[s].kind, openIndex: stack[s].openIndex });
    const stub = entries[entries.length - 1];
    closeRegion(stack[s], { index: stub ? stub.index : -1, name: '<<EOF>>' });
  }
  regions.sort((a, b) => a.openIndex - b.openIndex);

  const innermostRegion = (index) => {
    let best = null;
    for (const r of regions) {
      if (r.openIndex < index && (r.closeIndex < 0 || index < r.closeIndex)) {
        if (!best || r.openIndex > best.openIndex) best = r;
      }
    }
    return best;
  };
  for (const e of entries) e.region = innermostRegion(e.index);

  // 3) 角色判定
  for (const e of entries) {
    if (e.kind === 'layer-open' || e.kind === 'layer-close') {
      e.role2 = 'layer-locked';
      e.lockedOpen = true;
      continue;
    }
    if (e.region && e.region.kind === 'wrapper') {
      e.role2 = 'wrapper-part';
      continue;
    }
    if (e.region && e.region.kind === 'layer') {
      if (e.name.endsWith(VAR_SUFFIX)) e.role2 = 'var';
      else if (e.name.endsWith(MODEL_SUFFIX)) e.role2 = 'model-registry';
      else if (e.name.endsWith(CARD_ONCE) || e.name.endsWith(CARD_ANY)) e.role2 = 'card-head';
      else e.role2 = 'item';
      continue;
    }
    if (e.kind === 'wrapper-close' || e.kind === 'wrapper-open') {
      e.role2 = 'wrapper-part';
      continue;
    }
    if (e.name.endsWith(VAR_SUFFIX)) {
      e.role2 = 'var';
      issues.push({ level: 'warn', kind: 'var-entry-outside-any-layer', identifier: e.identifier, name: e.name });
      continue;
    }
    if (e.name.endsWith(MODEL_SUFFIX)) {
      e.role2 = 'model-registry';
      issues.push({ level: 'info', kind: 'model-registry-outside-any-layer', identifier: e.identifier, name: e.name });
      continue;
    }
    if (e.marker) {
      e.role2 = 'marker';
      continue;
    }
    e.role2 = 'structure';
  }

  // 4) 层级内部：卡片组装 + 零条目卡片降级
  const layerRegions = regions.filter((r) => r.kind === 'layer');
  const wrapperRegions = regions.filter((r) => r.kind === 'wrapper');
  for (const r of layerRegions) {
    r.entryList = r.children.filter((c) => c.role2 !== 'layer-locked');
    const segs = [];
    let cur = null;
    for (const c of r.entryList) {
      if (c.role2 === 'card-head') {
        const suffix = c.name.endsWith(CARD_ONCE) ? CARD_ONCE : CARD_ANY;
        cur = {
          name: c.name.slice(0, c.name.length - suffix.length).trim(),
          rawName: c.name,
          mode: suffix === CARD_ONCE ? '单选' : '多选',
          suffix: suffix,
          head: c,
          items: [],
        };
        c.cardName = cur.name;
        segs.push({ type: 'card', card: cur });
      } else if (cur) {
        cur.items.push(c);
        c.card = cur;
      } else {
        segs.push({ type: 'item', entry: c });
      }
    }
    const cards = [];
    const blocks = [];
    r.ownItems = [];
    for (const seg of segs) {
      if (seg.type === 'item') {
        blocks.push(seg);
        r.ownItems.push(seg.entry);
        continue;
      }
      if (seg.card.items.length === 0) {
        seg.card.head.role2 = 'item';
        seg.card.head.cardDemoted = true;
        seg.card.head.cardDemoteReason = 'empty';
        seg.card.head.cardName = null;
        r.ownItems.push(seg.card.head);
        blocks.push({ type: 'item', entry: seg.card.head });
      } else {
        cards.push(seg.card);
        blocks.push(seg);
      }
    }
    r.cards = cards;
    r.segments = blocks;
    r.vars = r.entryList.filter((c) => c.role2 === 'var');
    r.registries = r.entryList.filter((c) => c.role2 === 'model-registry');
    r.items = r.entryList.filter((c) => c.role2 === 'item');
    r.hasTab = cards.length > 0 || r.vars.length > 0;
    r.skipReason = r.hasTab ? null : '无卡片且无变量条目';
    for (const c of cards) {
      for (const it of c.items) it.inCard = c.name;
    }
    for (const it of r.ownItems) it.inCard = null;
  }

  // 5) 模型登记表
  const registryEntries = entries.filter((e) => e.role2 === 'model-registry');
  const table = [];
  for (const reg of registryEntries) {
    const rows = parseModelTable(reg.content);
    for (const row of rows) table.push({ emoji: row.emoji, label: row.label, from: reg.identifier, fromName: reg.name });
  }

  // 6) 模型归属
  const modelMembers = [];
  for (const e of entries) {
    if (e.role2 === 'layer-locked' || e.role2 === 'wrapper-part' || e.role2 === 'structure' || e.role2 === 'marker' || e.role2 === 'model-registry') continue;
    const hit = table.filter((m) => e.name.indexOf(m.emoji) >= 0);
    if (hit.length === 0) continue;
    e.models = hit.map((m) => m.emoji);
    e.modelLabels = hit.map((m) => m.label);
    e.modelExclusive = true;
    modelMembers.push(e);
  }
  // 非内容条目（卡片头/层级/结构）命中 emoji 的提示
  for (const e of entries) {
    if (e.models.length > 0) continue;
    const hit = table.filter((m) => e.name.indexOf(m.emoji) >= 0);
    if (hit.length > 0) {
      issues.push({ level: 'warn', kind: 'non-content-entry-matches-model-emoji', identifier: e.identifier, name: e.name, role2: e.role2, emojis: hit.map((m) => m.emoji) });
    }
  }

  // 6.5) 规则 15（收窄版）：模型专属卡片降级
  //      生效条件（**两个都要满足**）：
  //        a) 这张卡片是它所在层级里**唯一的卡片**（r.cards.length === 1）
  //        b) 它名下的条目「全部」都是模型专属条目（每条的模型归属集合 e.models 都非空）
  //      命中后：
  //        - 卡片头降级成该层级的普通条目（cardDemoted=true，cardDemoteReason='model-exclusive-items'）
  //        - 名下条目变成该层级的裸放条目（card=null）→ 没有「原卡片」可用于镜像标注
  //        - 卡片从 r.cards 里移除 → 该层级必然变成「无卡片无变量」→ 按规则 8 不出 tab
  //      收窄的后果（用户裁定）：层级里只要还有别的卡片，本规则一律不动手 —— 那些卡片
  //      照旧是卡片，名下模型专属条目照旧是卡片内条目（仍镜像进「🤖 模型」tab）。
  //      本规则**不删除任何条目**：模型专属条目照旧进全局「🤖 模型」tab（步骤 7 按名字里的
  //      emoji 收集），所以层级 tab 消失不会让这些条目从面板上消失。
  //      本步骤必须排在 6)（模型归属）之后、7)（tab 组装）之前。
  //      同时留下一张全量扫描表 cardModelScan（每个层级每张卡片一行），供报告核对。
  const modelExclusiveDemotions = [];
  const cardModelScan = [];
  const modelExclusiveKeptNotSole = [];
  for (const r of layerRegions) {
    const keptCards = [];
    const demotedCards = [];
    for (const c of r.cards) {
      const modelItems = c.items.filter((it) => it.models.length > 0);
      const nonModelItems = c.items.filter((it) => it.models.length === 0);
      const allModelExclusive = c.items.length > 0 && nonModelItems.length === 0;
      const soleCardInLayer = r.cards.length === 1;
      const demote = allModelExclusive && soleCardInLayer;
      cardModelScan.push({
        layer: r.name,
        card: c.name,
        rawName: c.rawName,
        itemCount: c.items.length,
        modelExclusiveItemCount: modelItems.length,
        modelExclusiveItemNames: modelItems.map((it) => it.name),
        nonModelItemNames: nonModelItems.map((it) => it.name),
        allModelExclusive: allModelExclusive,
        soleCardInLayer: soleCardInLayer,
        layerCardCount: r.cards.length,
        verdict: demote ? 'demoted' : (allModelExclusive ? 'kept-not-sole-card' : 'kept'),
      });
      if (!demote) {
        keptCards.push(c);
        if (allModelExclusive) {
          modelExclusiveKeptNotSole.push({
            layer: r.name,
            card: c.name,
            mode: c.mode,
            headIdentifier: c.head.identifier,
            headName: c.head.name,
            headEnabled: c.head.enabled,
            layerCardCount: r.cards.length,
            layerOtherCards: r.cards.filter((x) => x !== c).map((x) => x.name),
            itemCount: c.items.length,
            itemNames: c.items.map((it) => it.name),
            itemIdentifiers: c.items.map((it) => it.identifier),
            itemModels: c.items.map((it) => it.models.slice()),
          });
        }
        continue;
      }
      demotedCards.push(c);
      c.demotedByModelRule = true;
      c.head.role2 = 'item';
      c.head.cardDemoted = true;
      c.head.cardDemoteReason = 'model-exclusive-items';
      c.head.cardName = null;
      c.head.inCard = null;
      c.head.demotedFromCard = c.name;
      for (const it of c.items) {
        it.card = null;
        it.inCard = null;
        it.demotedFromCard = c.name;
      }
      modelExclusiveDemotions.push({
        layer: r.name,
        card: c.name,
        rawName: c.rawName,
        mode: c.mode,
        headIdentifier: c.head.identifier,
        headName: c.head.name,
        headEnabled: c.head.enabled,
        headContentLength: c.head.contentLength,
        itemCount: c.items.length,
        itemNames: c.items.map((it) => it.name),
        itemIdentifiers: c.items.map((it) => it.identifier),
        itemModels: c.items.map((it) => it.models.slice()),
        openIndex: r.openIndex,
        closeIndex: r.closeIndex,
      });
    }
    if (demotedCards.length === 0) continue;
    r.cards = keptCards;
    // 段落与裸放条目重排：被降级的卡片头 + 名下条目都变成该层级的裸放条目（保持原有的先后顺序）
    const segs2 = [];
    const own = [];
    for (const seg of r.segments) {
      if (seg.type === 'item') {
        segs2.push(seg);
        own.push(seg.entry);
        continue;
      }
      if (seg.card.demotedByModelRule) {
        segs2.push({ type: 'item', entry: seg.card.head });
        own.push(seg.card.head);
        for (const it of seg.card.items) {
          segs2.push({ type: 'item', entry: it });
          own.push(it);
        }
        continue;
      }
      segs2.push(seg);
    }
    r.segments = segs2;
    r.ownItems = own;
    r.items = r.entryList.filter((c) => c.role2 === 'item');
    r.hasTab = r.cards.length > 0 || r.vars.length > 0;
    r.skipReason = r.hasTab ? null : '无卡片且无变量条目';
  }

  // 7) tab 组装
  const tabs = [];
  const skippedLayers = [];
  for (const r of layerRegions) {
    if (!r.hasTab) {
      skippedLayers.push({ name: r.name, reason: r.skipReason, items: r.items.slice(), index: r.openIndex, openIndex: r.openIndex, closeIndex: r.closeIndex });
      continue;
    }
    tabs.push({
      kind: 'layer',
      name: r.name,
      openIndex: r.openIndex,
      closeIndex: r.closeIndex,
      region: r,
      cards: r.cards.map((c) => ({
        name: c.name,
        mode: c.mode,
        headIdentifier: c.head.identifier,
        headEnabled: c.head.enabled,
        items: c.items,
        itemCount: c.items.length,
        source: 'layer',
      })),
      standaloneItems: r.ownItems.filter((x) => x.role2 === 'item'),
      varEntries: r.vars,
      varCards: [],
      modelMembers: [],
    });
  }
  for (const t of tabs) {
    for (const v of t.varEntries) {
      const built = buildVarCards(v);
      v.varCards = built.cards;
      t.varCards.push({ entry: v, cards: built.cards, allVars: built.allVars, numericVars: built.numericVars });
    }
  }

  /* 「🎛 [模式切换]」卡片（2026-10-14 用户点名）：
     预设里有一个叫「🎛 运行模式」的层级，里面放互斥的运行模式条目
     （🎲 剧情游玩 / 💬 对话讨论，未来可能更多）。
     它不是模型，所以不能混进模型卡片里 —— 用户明确要求"这个卡片不能影响模型选择"。
     做法：单独做成模型 tab 的**第一张卡**（mode: 'once'，单选语义与其它「选一」一致），
     条目直接引用层级里那些 content 条目本身，面板照常按 identifier 写 prompt_order。
     层级自己仍然不出 tab（没有卡片、没有变量条目），所以面板上不会多出一页。 */
  const modelTab = {
    kind: 'model',
    name: '模型',
    displayName: '🤖 模型',
    global: true,
    cards: table.map((m) => ({ name: m.emoji + ' ' + m.label, emoji: m.emoji, label: m.label, mode: null, items: [], itemCount: 0, source: 'model' })),
    standaloneItems: [],
    varEntries: [],
    varCards: [],
    registryEntries: registryEntries.slice(),
    table: table.slice(),
  };

  for (let i = 0; i < modelTab.cards.length; i++) {
    const card = modelTab.cards[i];
    for (const e of modelMembers) {
      if (e.models.indexOf(card.emoji) < 0) continue;
      const originCard = e.card ? e.card.name : null;
      const originLayer = e.region && e.region.kind === 'layer' ? e.region.name : null;
      card.items.push({
        entry: e,
        identifier: e.identifier,
        name: e.name,
        models: e.models.slice(),
        originLayer: originLayer,
        originCard: originCard,
        originCardDemoted: e.demotedFromCard ? e.demotedFromCard : null,
        originIndex: e.index,
        isMirror: originCard !== null,
        onlyInModelTab: originCard === null,
      });
    }
    card.itemCount = card.items.length;
  }
  tabs.push(modelTab);

  // 8) 锁定条目
  const locked = entries
    .filter((e) => e.role2 === 'layer-locked')
    .map((e) => ({
      identifier: e.identifier,
      shortId: e.shortId,
      name: e.name,
      index: e.index,
      enabled: e.enabled,
      orderEnabled: e.orderEnabled,
      promptEnabled: e.promptEnabled,
      which: e.kind === 'layer-open' ? '层级开' : '层级闭',
      layerName: stripArrowEnds(e.name),
    }));
  const lockedDisabled = locked.filter((x) => x.enabled === false);

  // 9) 结构区
  const structureItems = entries.filter((e) => e.role2 === 'structure');
  const wrapperParts = entries.filter((e) => e.role2 === 'wrapper-part');
  const markers = entries.filter((e) => e.role2 === 'marker');

  // 10) 可达性核查：不在任何 tab、也不是结构区/锁定/marker 的条目
  //     inTab   = 作为「内容条目」出现在某个 tab 里
  //     inPanel = 出现在面板上（含卡片头：它在面板上显示为卡片标题）
  const inTab = new Set();
  const inPanel = new Set();
  const asCardHead = new Set();
  for (const t of tabs) {
    for (const c of t.cards) {
      if (c.headIdentifier) {
        inPanel.add(c.headIdentifier);
        asCardHead.add(c.headIdentifier);
      }
      for (const it of c.items) {
        const id = it.entry ? it.entry.identifier : it.identifier;
        inTab.add(id);
        inPanel.add(id);
      }
    }
    for (const it of t.standaloneItems) {
      inTab.add(it.identifier);
      inPanel.add(it.identifier);
    }
    for (const v of t.varEntries) {
      inTab.add(v.identifier);
      inPanel.add(v.identifier);
    }
  }
  const unreachable = entries.filter((e) => {
    if (inPanel.has(e.identifier)) return false;
    if (e.role2 === 'structure') return false;
    if (e.role2 === 'wrapper-part') return false;
    if (e.role2 === 'layer-locked') return false;
    if (e.role2 === 'marker') return false;
    if (e.role2 === 'model-registry') return false;
    return true;
  });

  // 11) 统计
  const panelEntries = entries.filter((e) => inPanel.has(e.identifier));
  const contentEntries = entries.filter((e) => inTab.has(e.identifier) && (e.role2 === 'item' || e.role2 === 'var'));
  const commented = panelEntries.filter((e) => e.commentFlat !== null && e.commentFlat.length > 0);
  const commentedContent = contentEntries.filter((e) => e.commentFlat !== null && e.commentFlat.length > 0);
  const withCommentFlat = panelEntries.filter((e) => e.commentFlat !== null && e.commentFlat.length > 0);
  const layerTabs = tabs.filter((t) => t.kind === 'layer');
  const allCards = [];
  for (const t of layerTabs) for (const c of t.cards) allCards.push(c);
  const modelMemberIds = [];
  for (const e of modelMembers) if (modelMemberIds.indexOf(e.identifier) < 0) modelMemberIds.push(e.identifier);
  let modelMirrorCount = 0;
  let modelTabOccurrences = 0;
  for (const c of modelTab.cards) {
    for (const it of c.items) {
      modelTabOccurrences++;
      if (it.isMirror) modelMirrorCount++;
    }
  }
  const stats = {
    orderLength: entries.length,
    promptCount: prompts.length,
    layerCount: layerRegions.length,
    wrapperCount: wrapperRegions.length,
    tabCount: tabs.length,
    layerTabCount: layerTabs.length,
    cardCount: allCards.length,
    modelCardCount: modelTab.cards.length,
    panelEntryCount: panelEntries.length,
    contentEntryCount: contentEntries.length,
    cardHeadCount: asCardHead.size,
    varEntryCount: entries.filter((e) => e.role2 === 'var').length,
    varCount: 0,
    rangeCardCount: 0,
    numberCardCount: 0,
    modelCount: table.length,
    modelMemberEntryCount: modelMemberIds.length,
    modelTabOccurrences: modelTabOccurrences,
    modelMirrorCount: modelMirrorCount,
    modelOnlyCount: modelMembers.filter((e) => !e.card).length,
    modelOnlyOccurrences: modelTabOccurrences - modelMirrorCount,
    structureCount: structureItems.length,
    wrapperPartCount: wrapperParts.length,
    markerCount: markers.length,
    lockedCount: locked.length,
    lockedDisabledCount: lockedDisabled.length,
    commentedCount: withCommentFlat.length,
    commentCoverage: panelEntries.length === 0 ? 0 : withCommentFlat.length / panelEntries.length,
    commentedContentCount: commentedContent.length,
    unreachableCount: unreachable.length,
    skippedLayerCount: skippedLayers.length,
    demotedCardHeadCount: entries.filter((e) => e.cardDemoted === true).length,
    emptyCardDemoteCount: entries.filter((e) => e.cardDemoteReason === 'empty').length,
    modelExclusiveCardDemoteCount: entries.filter((e) => e.cardDemoteReason === 'model-exclusive-items').length,
    modelExclusiveCardCount: modelExclusiveDemotions.length,
    modelExclusiveCardItemCount: modelExclusiveDemotions.reduce((n, d) => n + d.itemCount, 0),
    modelExclusiveAllModelCardCount: cardModelScan.filter((c) => c.allModelExclusive).length,
    modelExclusiveKeptNotSoleCount: modelExclusiveKeptNotSole.length,
  };
  for (const t of layerTabs) {
    for (const vc of t.varCards) {
      for (const c of vc.cards) {
        stats.varCount += c.type === 'range' ? 2 : 1;
        if (c.type === 'range') stats.rangeCardCount++;
        else stats.numberCardCount++;
      }
    }
  }

  const layersBuilt = layerRegions.map((r) => ({
    name: r.name,
    openIndex: r.openIndex,
    closeIndex: r.closeIndex,
    hasTab: r.hasTab,
    skipReason: r.skipReason,
    cards: r.cards.map((c) => ({ name: c.name, rawName: c.rawName, mode: c.mode, items: c.items })),
    items: r.items,
    vars: r.vars,
    registries: r.registries,
    entries: r.entryList,
  }));

  return {
    meta: {
      characterId: orders[0].character_id,
      orderLength: entries.length,
      promptCount: prompts.length,
      presetName: preset.name,
    },
    entries: entries,
    regions: regions.map((r) => ({
      kind: r.kind,
      name: r.name,
      openIndex: r.openIndex,
      closeIndex: r.closeIndex,
      entryCount: r.closeIndex - r.openIndex + 1,
      innerCount: r.closeIndex - r.openIndex - 1,
      cardCount: r.kind === 'layer' ? r.cards.length : 0,
      varCount: r.kind === 'layer' ? r.vars.length : 0,
      hasTab: r.kind === 'layer' ? r.hasTab : false,
      skipReason: r.kind === 'layer' ? r.skipReason : '结构包裹区',
    })),
    layers: layersBuilt,
    wrappers: wrapperRegions.map((r) => ({
      name: r.name,
      openIndex: r.openIndex,
      closeIndex: r.closeIndex,
      entries: r.children.concat([r.openEntry, r.closeEntry]).sort((a, b) => a.index - b.index),
    })),
    tabs: tabs,
    modelTab: modelTab,
    modelTable: table,
    modelMembers: modelMembers,
    modelExclusiveDemotions: modelExclusiveDemotions,
    modelExclusiveKeptNotSole: modelExclusiveKeptNotSole,
    cardModelScan: cardModelScan,
    structure: { items: structureItems, wrapperParts: wrapperParts, markers: markers },
    locked: locked,
    lockedDisabled: lockedDisabled,
    skippedLayers: skippedLayers,
    unreachable: unreachable,
    panelEntries: panelEntries,
    contentEntries: contentEntries,
    commentedEntries: commented,
    commentedContentEntries: commentedContent,
    stats: stats,
    issues: issues,
  };
}

/* ════════════════════════════════════════════════════════════════════════════
 * 用户自定义文风（名字里带 ` | diy_write_style`）
 * ----------------------------------------------------------------------------
 * 四件事全在这里做，且全是纯函数（零 DOM、零全局、零 IO），所以能离线单测：
 *   ① 标记的解析与生成        isCustomStyleName / customStyleDisplay / buildCustomStyleName / parseCustomName
 *   ② 组归属（向上检索卡片头）resolveCustomGroup
 *   ③ 可选组清单              customStyleSections
 *   ④ 写入计划（纯数据）      planCustomStyleWrite / customStyleEntries
 * IO 只留在 40-预设设置.js 的一层薄壳里：读活设置 → 调 planCustomStyleWrite → 写回两个数组 → 点保存按钮。
 *
 * 组归属为什么不用「名字带组名」：用户 2026-10-02 拍板 —— 归属靠**向上检索最近的 [组名] 卡片头**。
 * 这里的「向上」指**解析出来的序列**（tree.tabs[].cards[].items），不是 prompts[] 下标 ——
 * 解析器根本不按 prompts[] 顺序走，它走 prompt_order[0].order（见 parsePreset 第 1 步）。
 * ══════════════════════════════════════════════════════════════════════════ */

function diyText(v) { return (v === null || v === undefined) ? '' : String(v); }
/* 只做 JSON 深拷贝：进出的都是纯 JSON 数据，不引结构化克隆，老宿主也能跑 */
function diyClone(v) { return (v === undefined) ? undefined : JSON.parse(JSON.stringify(v)); }

function isCustomStyleName(name) {
  return diyText(name).endsWith(DIY_SUFFIX);
}

/* 名字 → 界面上显示的纯名字。不带标记的原样返回（面板上两种条目都要能显示）。 */
function customStyleDisplay(name) {
  const s = diyText(name);
  return isCustomStyleName(s) ? s.slice(0, s.length - DIY_SUFFIX.length).trim() : s;
}

/* 界面上的纯名字 → 写进预设的名字。起不出合法名字时返回 null（调用方报错，绝不猜）。 */
function buildCustomStyleName(display) {
  const s = diyText(display).trim();
  if (!s) { return null; }
  /* 名字里不许再出现标记本身：否则解析会认到最后一处、显示名里残留一段 */
  if (s.indexOf(DIY_SUFFIX) >= 0) { return null; }
  /* 不许有换行：条目名里有换行会把面板上的卡片名撑坏 */
  if (s.indexOf(String.fromCharCode(10)) >= 0 || s.indexOf(String.fromCharCode(13)) >= 0) { return null; }
  return s + DIY_SUFFIX;
}

function parseCustomName(name) {
  const s = diyText(name);
  if (!isCustomStyleName(s)) { return { ok: false, reason: 'not-custom', display: s, name: s }; }
  const display = s.slice(0, s.length - DIY_SUFFIX.length).trim();
  if (!display) { return { ok: false, reason: 'empty-display', display: '', name: s }; }

  return { ok: true, reason: null, display: display, name: s };
}

/* ── ② 组归属：在解析出来的序列里向上检索最近的卡片头 ──
   返回 null = 这个条目不在任何 layer tab 的卡片里（掉出组的游离项，即互斥失效的那种形态）。 */
function resolveCustomGroup(tabs, identifier) {
  const list = Array.isArray(tabs) ? tabs : [];
  const id = diyText(identifier);
  if (!id) { return null; }
  for (let i = 0; i < list.length; i++) {
    const t = list[i];
    if (!t || t.kind !== 'layer' || !Array.isArray(t.cards)) { continue; }
    for (let j = 0; j < t.cards.length; j++) {
      const c = t.cards[j];
      const items = (c && c.items) || [];
      for (let k = 0; k < items.length; k++) {
        if (diyText(items[k] && items[k].identifier) === id) {
          return {
            layerName: diyText(t.name),
            cardName: diyText(c.name),
            cardMode: diyText(c.mode),
            headIdentifier: diyText(c.headIdentifier),
            memberIndex: k,
            memberCount: items.length,
          };
        }
      }
    }
  }
  return null;
}

/* ── 对话模式（2026-10-14 用户点名；2026-10-15 按用户要求扩范围）──────────────
   「对话讨论」是运行模式之一，和「🎲 剧情游玩」互斥（模式卡是单选）。
   选中对话讨论时，要把「跑团专属」的那些组**整层**关掉，让位给元讨论：
     · 创作要求 / 角色塑造 / 写作指导 / 额外任务
     · 推理选项 —— **含「推理格式」**
   ⚠️ 2026-10-15 用户裁定：推理选项里**所有**条目都要纳入快照与关停。
      推理格式那三条（DeepSeek强强 / GLM偷偷 / Gemini糖糖）都是给跑团用的思维模板，
      对话讨论不该沿用它们；关掉并记住原样，切回「剧情游玩」时照旧恢复。
   返回 { groups: [{ layer, card, identifiers[] }], identifiers[] }：
     identifiers 是**去重后**的全部目标条目，调用方直接拿去存快照与关开关。
   纯函数：只读解析结果，不碰 DOM、不碰酒馆 API。 */
function dialogModeTargets(tabs) {
  /* 这五个层级整层关。⚠️ 名字是**包含**匹配：层级名带 🔻/🔺 标记，
     而「🎛 运行模式」不命中任何一个键 —— 模式条目自己永远不会被当成目标。 */
  const LAYERS = ['创作要求', '角色塑造', '写作指导', '额外任务', '推理选项'];
  const groups = [];
  const seen = {};
  const identifiers = [];
  for (const tab of (tabs || [])) {
    const tabName = String(tab && tab.name ? tab.name : '');
    let hit = false;
    for (const key of LAYERS) { if (tabName.indexOf(key) >= 0) { hit = true; break; } }
    if (!hit) { continue; }
    for (const card of (tab.cards || [])) {
      const cardName = String(card && card.name ? card.name : '');
      const ids = [];
      for (const it of (card.items || [])) {
        if (!it || !it.identifier) { continue; }
        ids.push(it.identifier);
        if (!seen[it.identifier]) { seen[it.identifier] = 1; identifiers.push(it.identifier); }
      }
      if (ids.length) { groups.push({ layer: tabName, card: cardName, identifiers: ids }); }
    }
  }
  return { groups: groups, identifiers: identifiers };
}

/* ── ③ 可选组清单：写作指导分区下的所有 [组名] 卡片头 ──
   找分区用的是**层级配对逻辑**（layer tab 名），不是字符串切分。
   anchorCardNames 是可选的额外锚点：调用方把手头已有的「文风页卡片名」传进来，
   卡片改名后仍能命中（引导的 PAGE_GROUPS 就是那份名单，不另立一份真相）。 */
function customStyleSections(tabs, anchorCardNames) {
  const list = Array.isArray(tabs) ? tabs : [];
  const anchors = (Array.isArray(anchorCardNames) ? anchorCardNames : []).map(diyText).filter(Boolean);
  let hit = null, via = null;
  for (let i = 0; i < list.length && !hit; i++) {
    const t = list[i];
    if (!t || t.kind !== 'layer' || !Array.isArray(t.cards)) { continue; }
    for (let j = 0; j < t.cards.length; j++) {
      if (anchors.indexOf(diyText(t.cards[j] && t.cards[j].name)) >= 0) { hit = t; via = 'anchor'; break; }
    }
  }
  if (!hit) {
    for (let i = 0; i < list.length; i++) {
      const t = list[i];
      if (t && t.kind === 'layer' && diyText(t.name).indexOf(DIY_LAYER_HINT) >= 0) { hit = t; via = 'layer-name'; break; }
    }
  }
  if (!hit) { return null; }
  return {
    via: via,
    layerName: diyText(hit.name),
    /* 分区收尾标记（📝 写作指导🔺）的 identifier。插入位置计算要用它当**最后一道边界** ——
       少了它，分区里最后一张卡的"组尾"会被算成整个预设的末尾，自定义条目就插到分区外面去了。 */
    closeIdentifier: diyText(hit.region && hit.region.closeEntry && hit.region.closeEntry.identifier),
    cards: (hit.cards || []).map((c) => ({
      cardName: diyText(c && c.name),
      cardMode: diyText(c && c.mode),
      headIdentifier: diyText(c && c.headIdentifier),
      members: ((c && c.items) || []).map((it) => ({
        identifier: diyText(it && it.identifier),
        name: diyText(it && it.name),
        enabled: !(it && it.enabled === false),
      })),
    })),
  };
}

/* ── ④ 写入计划（纯数据） ──
   input = {
     prompts, order,                 // 活设置里的两个数组（不会被改动，内部深拷贝）
     orderEntryCount, charId,        // prompt_order 的结构断言读数（R3）
     groups,                         // customStyleSections(...).cards
     adds, updates, removes,         // 界面攒下来的改动
     newId                           // 可注入的 id 生成器（单测里给固定值）
   }
   返回 { ok, code, detail, nextPrompts, nextOrder, report }
   —— 调用方拿 next* 直接写回活设置；任何一步不对就 ok:false，一个字节都不动。 */

function diyIndexOfId(arr, id) {
  for (let i = 0; i < arr.length; i++) { if (diyText(arr[i] && arr[i].identifier) === id) { return i; } }
  return -1;
}
function diyDupIds(arr) {
  const seen = {}, dup = [];
  for (let i = 0; i < arr.length; i++) {
    const id = diyText(arr[i] && arr[i].identifier);
    if (!id) { continue; }
    if (seen[id]) { if (dup.indexOf(id) < 0) { dup.push(id); } } else { seen[id] = 1; }
  }
  return dup;
}
function diyGroupOf(groups, headId) {
  for (let i = 0; i < groups.length; i++) {
    if (diyText(groups[i] && groups[i].headIdentifier) === headId) { return groups[i]; }
  }
  return null;
}
/* 目标组在 order[] 里的**尾巴下标**（含后来加进去的自定义条目，不是成员表的快照）。
   边界 = 下一个卡片头 或 分区收尾标记，取更靠前的那个。
   ⚠️ 最后一道边界（分区收尾）不能省：少了它，分区里最后一张卡的组尾会一路算到
      整个预设的末尾，自定义条目就被插到「写作指导」分区外面去了。 */
function diyGroupTailIndex(order, groups, g, sectionEndId) {
  const headIdx = diyIndexOfId(order, diyText(g && g.headIdentifier));
  if (headIdx < 0) { return -1; }
  let end = -1;
  for (let i = 0; i < groups.length; i++) {
    if (groups[i] === g) { continue; }
    const hi = diyIndexOfId(order, diyText(groups[i] && groups[i].headIdentifier));
    if (hi > headIdx && (end < 0 || hi < end)) { end = hi; }
  }
  if (sectionEndId) {
    const si = diyIndexOfId(order, sectionEndId);
    if (si > headIdx && (end < 0 || si < end)) { end = si; }
  }
  return (end < 0 ? order.length : end) - 1;
}
/* 克隆模板：组里**最后一个还存在于 prompts[]** 的成员（成员表可能因同一批的删除而变旧）。 */
function diyTemplateId(prompts, g) {
  const ms = (g && g.members) || [];
  for (let i = ms.length - 1; i >= 0; i--) {
    const id = diyText(ms[i] && ms[i].identifier);
    if (id && diyIndexOfId(prompts, id) >= 0) { return id; }
  }
  return null;
}

function planCustomStyleWrite(input) {
  const src = input || {};
  const report = {
    added: [], updated: [], removed: [], orderMoved: [], deselected: [],
    names: {}, before: null, after: null,
  };
  function fail(code, detail) {
    return { ok: false, code: code, detail: diyText(detail), nextPrompts: null, nextOrder: null, report: report };
  }

  if (!Array.isArray(src.prompts)) { return fail('NO_PROMPTS'); }
  if (!Array.isArray(src.order)) { return fail('NO_ORDER'); }
  /* R3：写入前断言 prompt_order 结构，不符合预期就放弃写入并明确报错，绝不猜 */
  if (src.orderEntryCount !== DIY_ORDER_COUNT) { return fail('ORDER_SHAPE', 'prompt_order 条数=' + diyText(src.orderEntryCount)); }
  if (src.charId !== DIY_CHAR_ID) { return fail('ORDER_SHAPE', 'character_id=' + diyText(src.charId)); }

  const prompts = diyClone(src.prompts);
  const order = diyClone(src.order);
  const groups = Array.isArray(src.groups) ? src.groups : [];
  const adds = Array.isArray(src.adds) ? src.adds : [];
  const updates = Array.isArray(src.updates) ? src.updates : [];
  const removes = Array.isArray(src.removes) ? src.removes : [];
  const newId = (typeof src.newId === 'function') ? src.newId : null;
  /* 分区收尾标记：插入位置的最后一道边界（见 diyGroupTailIndex 的注释） */
  const sectionEndId = diyText(src.sectionEndId);

  const dupP = diyDupIds(prompts), dupO = diyDupIds(order);
  if (dupP.length) { return fail('DUP_ID', dupP.join(',')); }
  if (dupO.length) { return fail('DUP_ID', dupO.join(',')); }

  report.before = { prompts: prompts.length, order: order.length };

  /* ① 删：两个数组同删（R1 硬阻断，绝不留孤儿）。
        只肯删带标记的条目 —— 防止误删预设原有的条目。 */
  for (let i = 0; i < removes.length; i++) {
    const id = diyText(removes[i]);
    const pi = diyIndexOfId(prompts, id), oi = diyIndexOfId(order, id);
    if (pi < 0 || oi < 0) { return fail('REMOVE_MISSING', id); }
    if (!isCustomStyleName(prompts[pi].name)) { return fail('REMOVE_NOT_CUSTOM', id); }
    prompts.splice(pi, 1);
    order.splice(oi, 1);
    report.removed.push(id);
  }

  /* ② 改：改名字 / 正文；换组 = 在 order 里搬家（位置就是归属，见文件头） */
  for (let i = 0; i < updates.length; i++) {
    const u = updates[i] || {};
    const id = diyText(u.identifier);
    const pi = diyIndexOfId(prompts, id), oi = diyIndexOfId(order, id);
    if (pi < 0 || oi < 0) { return fail('UPDATE_MISSING', id); }
    if (!isCustomStyleName(prompts[pi].name)) { return fail('UPDATE_NOT_CUSTOM', id); }
    const nm = buildCustomStyleName(u.display);
    if (!nm) { return fail('BAD_NAME', diyText(u.display)); }
    prompts[pi].name = nm;
    report.names[id] = nm;
    if (typeof u.content === 'string') { prompts[pi].content = u.content; }
    report.updated.push(id);
    if (u.groupHeadId) {
      const g = diyGroupOf(groups, diyText(u.groupHeadId));
      if (!g) { return fail('GROUP_NOT_FOUND', diyText(u.groupHeadId)); }
      const tailIdx = diyGroupTailIndex(order, groups, g, sectionEndId);
      if (tailIdx < 0) { return fail('GROUP_TAIL_MISSING', diyText(u.groupHeadId)); }
      const from = diyIndexOfId(order, id);
      /* 本来就已经在这一组的末尾 → 原地不动，别做无意义的搬家 */
      if (from !== tailIdx) {
        const item = order.splice(from, 1)[0];
        const tail2 = diyGroupTailIndex(order, groups, g, sectionEndId);
        if (tail2 < 0) { return fail('GROUP_TAIL_MISSING', diyText(u.groupHeadId)); }
        order.splice(tail2 + 1, 0, item);
        report.orderMoved.push(id);
      }
    }
  }

  /* ③ 增：**克隆同组现有条目的完整字段表**（R2 的缓解措施），只覆盖三个字段；
        两个数组同插（R1）。 */
  for (let i = 0; i < adds.length; i++) {
    const a = adds[i] || {};
    const g = diyGroupOf(groups, diyText(a.groupHeadId));
    if (!g) { return fail('GROUP_NOT_FOUND', diyText(a.groupHeadId)); }
    const nm = buildCustomStyleName(a.display);
    if (!nm) { return fail('BAD_NAME', diyText(a.display)); }
    const id = newId ? diyText(newId()) : '';
    if (!id) { return fail('NO_ID'); }
    if (diyIndexOfId(prompts, id) >= 0 || diyIndexOfId(order, id) >= 0) { return fail('DUP_ID', id); }
    const tailIdx = diyGroupTailIndex(order, groups, g, sectionEndId);
    if (tailIdx < 0) { return fail('GROUP_TAIL_MISSING', diyText(a.groupHeadId)); }
    const tplId = diyTemplateId(prompts, g);
    if (!tplId) { return fail('GROUP_EMPTY', diyText(a.groupHeadId)); }
    const tplPi = diyIndexOfId(prompts, tplId);
    const item = diyClone(prompts[tplPi]);
    item.identifier = id;
    item.name = nm;
    item.content = (typeof a.content === 'string') ? a.content : '';
    const at = tplPi + 1;
    prompts.splice(at, 0, item);
    const oi = tailIdx + 1;
    order.splice(oi, 0, { identifier: id, enabled: false });
    report.added.push({
      identifier: id, display: customStyleDisplay(nm), groupHeadId: diyText(a.groupHeadId),
      promptsAt: at, orderAt: oi, clonedFrom: tplId,
    });
    report.names[id] = nm;
  }

  /* ④ 新增即选中；目标组是选一就把同组其它条目关掉（用户拍板第 5 条）。
        同一组里一次加多条时只留最后一条选中，免得自己把自己顶掉。 */
  const byGroup = {};
  const addOrder = [];
  for (let i = 0; i < report.added.length; i++) {
    const rec = report.added[i];
    if (!byGroup[rec.groupHeadId]) { byGroup[rec.groupHeadId] = []; addOrder.push(rec.groupHeadId); }
    byGroup[rec.groupHeadId].push(rec.identifier);
    const oi = diyIndexOfId(order, rec.identifier);
    if (oi >= 0) { order[oi].enabled = false; }
  }
  for (let i = 0; i < addOrder.length; i++) {
    const headId = addOrder[i];
    const mine = byGroup[headId];
    const keep = mine[mine.length - 1];
    const keepOi = diyIndexOfId(order, keep);
    if (keepOi >= 0) { order[keepOi].enabled = true; }
    const g = diyGroupOf(groups, headId);
    if (!g || diyText(g.cardMode) !== '单选') { continue; }
    const ms = g.members || [];
    const others = [];
    for (let j = 0; j < ms.length; j++) {
      const mid = diyText(ms[j] && ms[j].identifier);
      if (mid) { others.push(mid); }
    }
    for (let j = 0; j < mine.length; j++) { if (mine[j] !== keep) { others.push(mine[j]); } }
    for (let j = 0; j < others.length; j++) {
      const oi = diyIndexOfId(order, others[j]);
      if (oi >= 0 && order[oi].enabled !== false) {
        order[oi].enabled = false;
        if (report.deselected.indexOf(others[j]) < 0) { report.deselected.push(others[j]); }
      }
    }
  }

  report.after = { prompts: prompts.length, order: order.length };
  return { ok: true, code: null, detail: '', nextPrompts: prompts, nextOrder: order, report: report };
}

/* ── 读侧：把当前预设里的自定义文风连同它的组一起列出来 ──
   orphan = true 表示这条虽然带标记、但已经**掉出所有卡片组**（互斥对它失效）。 */
function customStyleEntries(prompts, order, tabs) {
  const out = [];
  const list = Array.isArray(prompts) ? prompts : [];
  const ord = Array.isArray(order) ? order : [];
  for (let i = 0; i < ord.length; i++) {
    const id = diyText(ord[i] && ord[i].identifier);
    if (!id) { continue; }
    let p = null;
    for (let j = 0; j < list.length; j++) {
      if (diyText(list[j] && list[j].identifier) === id) { p = list[j]; break; }
    }
    if (!p) { continue; }
    const parsed = parseCustomName(p.name);
    if (!parsed.ok) { continue; }
    const g = resolveCustomGroup(tabs, id);
    out.push({
      identifier: id,
      display: parsed.display,
      name: diyText(p.name),
      content: (typeof p.content === 'string') ? p.content : '',
      enabled: ord[i].enabled !== false,
      groupHeadId: g ? g.headIdentifier : null,
      groupName: g ? g.cardName : null,
      groupMode: g ? g.cardMode : null,
      orphan: !g,
    });
  }
  return out;
}



  /* ── 「自动标签处理」的纯逻辑（唯一真相：src/scripts/_tags-pure.js，构建期内联） ──
     为什么要它：「🧰 其他功能」页上的开关要能检测 AI 回复里没闭合的标签并补上/删掉。
     认标签、决定补在哪儿、删哪一段全在那份模块里，这里是它的唯一消费者；
     标签名单（哪些标签算数、谁在消费它们）也写在那个文件的表里，改表就两边一起变。 */
  /* ============================================================================
 * 卡密预设 · 标签处理（纯逻辑，构建期内联进 40-预设设置.js）
 * ----------------------------------------------------------------------------
 * 干什么：AI 回复里的成对标签（`<content>…</content>` 这种）**没闭合**时，把结尾补上，
 *   或者把配不上对的标签本身删掉。检测与改写全在这里，一行 DOM / 一行酒馆 API 都没有 ——
 *   于是可以离线单测（test/harness/tags-pure.mjs），也不用为了改一句话去开浏览器。
 *
 * 为什么要管（谁在消费这些标签，见 docs/皮肤契约.md §5 与 src/regex/list.json）：
 *   标签名单的**唯一真相**是预设条目「🧩 标签格式」（src/preset.base.json，用
 *   `{{setvar::content_start::<content>}}` 的形式把全部标签列了一遍）。逐个对应：
 *
 *   <out_body>        总标签：包住正文与前后处理块    → 隐藏|XML结构间换行 A/B
 *   <introduction>    前处理块                        → 同上
 *   <content>         正文块                          → 前端|正文 v0.1（缺闭合 ⇒ 整块外壳不出现）
 *   <appendix>        后处理块                        → 隐藏|XML结构间换行 A/B
 *   <think>           原生思维链（DeepSeek/GLM）      → 酒馆本体 reasoning.js 解析
 *   <nyaruko_think>   显式思维链（Gemini 等）         → 前端|显式思维链 v0.1
 *   <image>           文生图                          → 屏蔽|图片与<god>(仅保留一楼)
 *   <image_Tag>       图片标签                        → 同上
 *   <MakeImage>       生图指令                        → 同上
 *   <god>             ROOT 权限指令                   → 同上
 *   <medium>          正文里的 HTML 美化部件          → 屏蔽|HTML美化代码
 *   <medium_content>  HTML 美化的留档文字             → 隐藏|HTML美化留档文字
