      }
    } catch (e) { }
    return '';
  }

  /* 活设置的几个可能位置，按「最像当前预设」的顺序排 */
  function liveSettingsList(ctx, settings) {
    var out = [], i, cands = [settings, (ctx && ctx.chatCompletionSettings) || null, (HOST && HOST.oai_settings) || null];
