          ' https://github.com/' + encodeURIComponent(repoConfig().owner) + '/' +
          encodeURIComponent(repoConfig().repo) + '/releases 手动下载 ' + assetFileName(remote) + ' 导入酒馆';
        var er2 = new Error(friendly);
