      var ch = chain.channels[i];
      log('切到下载通道「' + ch.label + '」（' + (i + 1) + '/' + chain.channels.length + '）');
      /* 换通道 = 从头再下一遍，已下载字节要从 0 重算（不然进度条会来回跳） */
