    return cleanStr(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/\|/g, '｜')
      .replace(/\\/g, '＼')
      .replace(/\{/g, '｛')
      .replace(/\}/g, '｝');
