      if (r.status !== 200) { throw new Error('jsDelivr 清单也是 HTTP ' + r.status); }
      var m = null;
      try { m = JSON.parse(r.text); } catch (e) { throw new Error('jsDelivr 清单不是合法 JSON'); }
      var file = cleanStr(m.file), ver = cleanStr(m.version);
