var WEATHER_FALLBACK = '🌡️';

/** 天气文字 → 图标；认不出来的用兜底图标（不返回空，免得标题栏缺一块） */
function weatherIcon(w) {
  var k = String(w == null ? '' : w).trim();
  if (!k) { return ''; }
  return WEATHER_ICON[k] || WEATHER_FALLBACK;
